/* TruckLedger — no accounts, analytics, tracking scripts, or external dependencies.
   All user records and receipt files live in this browser's IndexedDB. */
'use strict';
const DB_NAME='truckledger-v1';
const DB_VERSION=2;
const STORES=['companies','trips','expenses','receipts','settings','audit'];
const $=s=>document.querySelector(s);
const state={tab:'dashboard',period:'month',trendMetric:'earned',trendFocus:-1,tripFilter:'all',expenseFilter:'all',companies:[],trips:[],expenses:[],receipts:[],settings:[],audit:[],db:null};
const fmtMoney=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(Number(n)||0);
const fmtNum=n=>new Intl.NumberFormat('en-CA',{maximumFractionDigits:1}).format(Number(n)||0);
const round=n=>Math.round(((Number(n)||0)+Number.EPSILON)*100)/100;
const number=v=>Number.isFinite(Number(v))?Number(v):0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const humanDate=d=>{if(!d)return 'Undated';const [y,m,day]=d.split('-').map(Number);if(!y||!m||!day)return esc(d);return new Date(y,m-1,day).toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric'});};
const uid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;
let toastTimer;
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function openDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('IndexedDB is unavailable in this browser. Open this app in Safari from a website.'));const req=indexedDB.open(DB_NAME,DB_VERSION);req.onupgradeneeded=()=>{for(const name of STORES){if(!req.result.objectStoreNames.contains(name))req.result.createObjectStore(name,{keyPath:'id'});}};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function dbOp(store,mode,operation){return new Promise((resolve,reject)=>{const tx=state.db.transaction(store,mode);const req=operation(tx.objectStore(store));let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error||new Error('Could not save data'));tx.onabort=()=>reject(tx.error||new Error('Save interrupted'));});}
const getAll=store=>dbOp(store,'readonly',s=>s.getAll());
const put=(store,record)=>dbOp(store,'readwrite',s=>s.put(record));
const remove=(store,id)=>dbOp(store,'readwrite',s=>s.delete(id));
const get=(store,id)=>dbOp(store,'readonly',s=>s.get(id));
function auditEvent(store,action,oldRecord,newRecord){return {id:uid(),at:new Date().toISOString(),entity:store,action,record_id:(newRecord||oldRecord)?.id||'',before:oldRecord||null,after:newRecord||null};}
function writeWithAudit(store,newRecord,oldRecord){return new Promise((resolve,reject)=>{const tx=state.db.transaction([store,'audit'],'readwrite');tx.objectStore(store).put(newRecord);tx.objectStore('audit').put(auditEvent(store,oldRecord?'update':'create',oldRecord,newRecord));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Save interrupted'));});}
async function refresh(){[state.companies,state.trips,state.expenses,state.receipts,state.settings,state.audit]=await Promise.all(['companies','trips','expenses','receipts','settings','audit'].map(getAll));render();}
function localDateKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function weekStart(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-(d.getDay()+6)%7);return d;}
function periodMatch(date){if(state.period==='all')return true;if(!date)return false;const d=today();if(state.period==='day')return date===d;if(state.period==='week'){const m=weekStart(),end=new Date(m);end.setDate(m.getDate()+6);return date>=localDateKey(m)&&date<=localDateKey(end);}return state.period==='month'?date.slice(0,7)===d.slice(0,7):date.slice(0,4)===d.slice(0,4);}
function tripDistance(t){if(t.end_km===null||t.end_km===undefined||t.end_km==='')return null;return Math.max(0,round((Number(t.end_km)-Number(t.start_km))*10)/10);}
// If a work trip has no manual billed distance, bill the driven distance as before.
// Historical records remain compatible with the new field.
function billedDistance(t){
 const driven=tripDistance(t);
 if(t.kind!=='work'||!t.bill_km||driven===null)return t.kind==='work'&&driven===null?null:0;
 const supplied=t.billed_km;
 return supplied===null||supplied===undefined||supplied===''?driven:number(supplied);
}
const DEFAULT_EARNINGS_SHARE=85;
function sharePercent(){const raw=state.settings.find(s=>s.id==='share_percent')?.value;const n=Number(raw);return raw!==undefined&&raw!==''&&Number.isFinite(n)&&n>=0&&n<=100?n:DEFAULT_EARNINGS_SHARE;}
function tripSharePercent(t){const n=Number(t.share_percent);return t.share_percent!==undefined&&t.share_percent!==null&&t.share_percent!==''&&Number.isFinite(n)&&n>=0&&n<=100?n:DEFAULT_EARNINGS_SHARE;}
/* Allocate the user's percentage of the full total across its components,
   including rounding cents. No employer's share is displayed. */
function splitEarnings(grossAmounts,pct){
 const cents=grossAmounts.map(a=>Math.round(round(a)*100));
 const raw=cents.map(n=>n*pct/100),earned=raw.map(n=>Math.floor(n+1e-9));
 const target=Math.round(cents.reduce((a,b)=>a+b,0)*pct/100);
 const remainder=target-earned.reduce((a,b)=>a+b,0);
 const sorted=raw.map((n,i)=>({i,d:n-earned[i]})).sort((a,b)=>b.d-a.d||a.i-b.i);
 for(let i=0;i<remainder;i++)earned[sorted[i%sorted.length].i]++;
 return earned.map(c=>c/100);
}
function calculate(t){const km=tripDistance(t);const rate=t.rate||{};/* Keep old hourly vehicle charges correct when an old trip had only the legacy 'hours' value. */const truckHours=number(t.truck_hours===''||t.truck_hours==null?t.hours:t.truck_hours);if(t.kind!=='work'||km===null)return {km,billedKm:t.kind==='work'&&km===null?null:0,kmCharge:0,truckCharge:0,surcharge:0,truckRevenue:0,total:0};
 const billedKm=billedDistance(t);
 const kmCharge=t.bill_km?round(billedKm*number(rate.km_rate)):0;
 const truckCharge=t.bill_truck_hours?round(truckHours*number(rate.truck_hour_rate)):0;
 let surcharge=0;if(t.bill_surcharge){switch(rate.surcharge_type){case'percent':surcharge=round((kmCharge+truckCharge)*number(rate.surcharge_rate)/100);break;case'per_km':surcharge=round(km*number(rate.surcharge_rate));break;case'per_hour':surcharge=round(truckHours*number(rate.surcharge_rate));break;case'flat':surcharge=round(number(rate.surcharge_rate));break;}}
 const [earnedKm,earnedTruck,earnedFuel]=splitEarnings([kmCharge,truckCharge,surcharge],tripSharePercent(t));const truckRevenue=round(earnedKm+earnedTruck+earnedFuel);return {km,billedKm,kmCharge:earnedKm,truckCharge:earnedTruck,surcharge:earnedFuel,truckRevenue,total:truckRevenue,sharePercent:tripSharePercent(t)};}
function getCompany(id){return state.companies.find(c=>c.id===id)}
const companyName=t=>t.client_name||getCompany(t.client_id)?.name||'Unassigned work';
function activeTrips(){return state.trips.filter(t=>periodMatch(t.date));}
function activeExpenses(){return state.expenses.filter(e=>periodMatch(e.date));}
function stats(){const trips=activeTrips();const expenses=activeExpenses();let workKm=0,personalKm=0,billableKm=0,billableTripActualKm=0,vehicleRevenue=0,open=0,workCount=0,kmEarnings=0,hourEarnings=0,surchargeEarnings=0;for(const t of trips){const c=calculate(t);if(c.km===null){open++;continue;}if(t.kind==='work'){workCount++;workKm+=c.km;if(t.bill_km){billableKm+=c.billedKm;billableTripActualKm+=c.km;}if(!FINANCES.covered(t)){vehicleRevenue+=c.truckRevenue;kmEarnings+=c.kmCharge;hourEarnings+=c.truckCharge;surchargeEarnings+=c.surcharge;}}else personalKm+=c.km;}
 const costs=round(expenses.reduce((sum,e)=>sum+number(e.amount),0)),fuel=round(expenses.filter(e=>e.category==='Fuel').reduce((sum,e)=>sum+number(e.amount),0)),maintenance=round(costs-fuel);const openings=FINANCES.periodRecords(state.period);for(const o of openings){const p=FINANCES.ownerParts(o);kmEarnings+=p.km;hourEarnings+=p.hours;surchargeEarnings+=p.fuel;}const openingRevenue=FINANCES.periodTotal(state.period),trackedRevenue=round(vehicleRevenue),total=round(openingRevenue+trackedRevenue);return {workKm,personalKm,billableKm,billableTripActualKm,extraBilledKm:round(billableKm-billableTripActualKm),vehicleRevenue:total,trackedRevenue,openingRevenue,openingCount:openings.length,kmEarnings:round(kmEarnings),hourEarnings:round(hourEarnings),surchargeEarnings:round(surchargeEarnings),costs,fuel,maintenance,net:round(total-costs),open,workCount,trips:trips.length};}
function periodDescription(){if(state.period==='day')return 'Today · '+new Date().toLocaleDateString('en-CA',{weekday:'long',month:'short',day:'numeric'});if(state.period==='week'){const m=weekStart(),s=new Date(m);s.setDate(m.getDate()+6);return m.toLocaleDateString('en-CA',{month:'short',day:'numeric'})+' – '+s.toLocaleDateString('en-CA',{month:'short',day:'numeric'});}if(state.period==='month')return new Date().toLocaleDateString('en-CA',{month:'long',year:'numeric'});if(state.period==='year')return 'Calendar year '+today().slice(0,4);return 'All recorded activity';}
function periodBar(){return `<div class="periodbar" role="group" aria-label="Reporting period">${[['day','Today'],['week','Week'],['month','Month'],['year','Year'],['all','All']].map(([v,t])=>`<button type="button" data-period="${v}" aria-pressed="${state.period===v}" class="${state.period===v?'active':''}">${t}</button>`).join('')}</div>`;}
function metric(title,value,tip='',klass='',counter=null){return `<div class="card metric ${klass}"><div class="metric-title">${title}</div><div class="metric-value" ${counter===null?'':`data-counter="${esc(title)}" data-counter-value="${counter}"`}>${value}</div>${tip?`<div class="metric-note">${tip}</div>`:''}</div>`;}
function chip(t){return `<span class="tag ${t.kind==='work'?'work':'personal'}">${t.kind==='work'?'WORK':'PERSONAL'}</span>`;}
function tripLine(t){const c=calculate(t),open=c.km===null;return `<div class="listitem"><button class="item-main" data-edit-trip="${esc(t.id)}"><div class="item-title">${chip(t)} ${esc(t.kind==='work'?companyName(t):(t.destination||'Personal drive'))}</div><div class="item-sub">${humanDate(t.date)} · ${esc(t.destination||t.purpose||'No destination')}${open?' · <span class="tag open">OPEN</span>':t.kind==='work'&&t.bill_km?` · ${fmtNum(c.billedKm)} km billed`:''}${t.kind==='work'&&FINANCES.covered(t)?' · <span class="tag">Included in YTD</span>':''}</div></button><div class="item-side"><div class="item-value">${open?'—':`${fmtNum(c.km)} km`}</div>${t.kind==='work'&&!open?`<div class="stat-caption">${fmtMoney(c.truckRevenue)} earned</div>`:''}</div><button class="icon-button" style="background:transparent;border:0;width:26px" aria-label="Edit trip" data-edit-trip="${esc(t.id)}">›</button></div>`;}
function expenseLine(e){return `<div class="listitem"><button class="item-main" data-edit-expense="${esc(e.id)}"><div class="item-title">${esc(e.category)} ${e.receipt_id?'📎':''}</div><div class="item-sub">${humanDate(e.date)} · ${esc(e.vendor||e.notes||'Vehicle expense')}</div></button><div class="item-value">${fmtMoney(e.amount)}</div><button class="icon-button" style="background:transparent;border:0;width:26px" aria-label="Edit cost" data-edit-expense="${esc(e.id)}">›</button></div>`;}
function pageDashboard(){const s=stats(),totalKm=s.workKm+s.personalKm,sort=(arr)=>arr.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.created_at||'').localeCompare(a.created_at||''));const last=sort(state.trips).slice(0,5);
 const companyTotals={};for(const t of activeTrips().filter(t=>t.kind==='work'&&tripDistance(t)!==null)){if(FINANCES.covered(t))continue;const k=companyName(t);companyTotals[k]=(companyTotals[k]||0)+calculate(t).truckRevenue;}
 const companyEntries=Object.entries(companyTotals).sort((a,b)=>b[1]-a[1]);const biggest=Math.max(1,...companyEntries.map(v=>v[1]));
 return `<div class="section-heading"><div><div class="eyebrow">TRUCK PERFORMANCE</div><h1>Overview</h1></div><span class="muted small">CAD · km</span></div>${periodBar()}
 <div class="overview-period-caption">${periodDescription()}</div>
 <div class="card hero overview-hero"><div class="eyebrow" style="color:#a5f4d8">YOUR EARNINGS</div><div class="hero-value" data-counter="earnings" data-counter-value="${s.vehicleRevenue}">${fmtMoney(s.vehicleRevenue)}</div><div class="hero-sub">Your share of truck income for this period</div>${s.openingCount?`<div class="overview-opening-note">${fmtMoney(s.openingRevenue)} opening YTD · ${fmtMoney(s.trackedRevenue)} new trips</div>`:""}</div>
 <div class="quick-actions overview-actions"><button class="btn" data-new-trip="work">＋ Work trip</button><button class="btn secondary" data-new-trip="personal">＋ Personal trip</button></div>
 <div class="grid2 overview-profit">${metric('Vehicle costs',fmtMoney(s.costs),'Recorded costs this period','gold',s.costs)}${metric('Operating profit',fmtMoney(s.net),'Earnings − recorded costs',s.net<0?'bad':'good',s.net)}</div>
 ${typeof TREND!=='undefined'&&TREND&&typeof TREND.chart==='function'?TREND.chart():''}
 <div class="card overview-mix"><div class="split-line"><strong>Earnings breakdown</strong><span class="muted small">${periodDescription()}</span></div>${[['Kilometres',s.kmEarnings],['Truck hours',s.hourEarnings],['Fuel surcharge',s.surchargeEarnings]].map(([name,value])=>`<div class="mix-row"><div class="mix-heading"><span>${name}</span><strong>${fmtMoney(value)}</strong></div><div class="mix-track"><div class="mix-fill" style="width:${100*value/Math.max(1,s.kmEarnings,s.hourEarnings,s.surchargeEarnings)}%"></div></div></div>`).join('')}${s.openingCount?'<p class="hint">Includes your opening YTD earnings, already net of Ace’s share.</p>':''}</div>
 <div class="subheading">Mileage</div>
 <div class="grid2 overview-distances">${metric('Work distance',`${fmtNum(s.workKm)} km`,'Actual odometer distance')}${metric('Personal distance',`${fmtNum(s.personalKm)} km`,'Not charged to clients')}</div>
 <div class="grid2 overview-distances">${metric('Billed kilometres',`${fmtNum(s.billableKm)} km`,'Distance charged to clients')}${metric('Extra billed distance',`${s.extraBilledKm>0?'+':''}${fmtNum(s.extraBilledKm)} km`,'Billed km minus actual km on billed trips',s.extraBilledKm>=0?'good':'gold')}</div>
 <div class="card"><div class="split-line"><strong>Distance breakdown</strong><span class="muted small">${fmtNum(totalKm)} km logged</span></div><div class="barrow"><span class="barlabel">Work</span><div class="bartrack"><div class="barfill" style="width:${totalKm?100*s.workKm/totalKm:0}%"></div></div><span class="barvalue">${totalKm?(s.workKm*100/totalKm).toFixed(0):0}%</span></div><div class="barrow"><span class="barlabel">Personal</span><div class="bartrack"><div class="barfill personal" style="width:${totalKm?100*s.personalKm/totalKm:0}%"></div></div><span class="barvalue">${totalKm?(s.personalKm*100/totalKm).toFixed(0):0}%</span></div></div>
 <div class="card"><div class="split-line"><strong>At-a-glance earnings & costs</strong><span class="muted small">${s.workCount} completed work trips</span></div>${[['Your truck earnings',s.vehicleRevenue],['Fuel spent',s.fuel],['Other vehicle costs',s.maintenance]].map(([k,v])=>`<div class="datum"><span>${k}</span><span>${fmtMoney(v)}</span></div>`).join('')}${s.open?`<div class="notice warning">${s.open} trip${s.open!==1?'s':''} waiting for a finishing odometer reading. Open trips do not count toward distance or revenue yet.</div>`:''}</div>
 ${companyEntries.length?`<div class="card"><div class="split-line"><strong>Your earnings by client</strong><button class="inline-link" data-nav="companies">All clients</button></div>${companyEntries.map(([name,value])=>`<div class="company-line"><div class="split-line"><span class="company-bar-label">${esc(name)}</span><span class="company-bar-value">${fmtMoney(value)}</span></div><div class="company-bar"><div style="width:${100*value/biggest}%"></div></div></div>`).join('')}</div>`:''}
 <div class="card"><div class="split-line"><strong>Recent trips</strong><button class="inline-link" data-nav="trips">View all</button></div>${last.length?last.map(tripLine).join(''):`<div class="empty"><div class="empty-icon">↗</div>Start by logging your first work or personal trip.</div>`}</div>
 <div class="screen-note">'Billed kilometres' includes only trips with km charging enabled. Extra billed distance compares those billed kilometres with actual odometer distance on the same trips. Opening YTD earnings are included in Year and All, never Today, Week or Month; the dated chart never invents historical trip dates. Trips dated within an opening balance are excluded from earnings totals to prevent double counting (their logged kilometres remain). Your operating profit subtracts recorded vehicle costs from your share of truck earnings. The company's retained portion is not included or displayed. Figures are estimates, not invoices or tax advice. Lifetime purchase recovery has moved to the Investment tab.</div>`;}
function pageInvestment(){const life=FINANCES.lifetime();const allSummary={openingRevenue:life.opening,trackedRevenue:life.tracked,vehicleRevenue:life.revenue,openingCount:FINANCES.periodRecords('all').length};return `<div class="section-heading"><div><div class="eyebrow">LONG-TERM PERFORMANCE</div><h1>Investment</h1></div><span class="muted small">All time</span></div><div class="card investment-hero"><div class="eyebrow">NET AFTER PURCHASE PRICE</div><div class="investment-big ${life.afterPurchase<0?'negative':'positive'}">${life.purchase?fmtMoney(life.afterPurchase):'Set purchase price'}</div><p class="hint">All-time earnings, minus recorded costs and the one-time truck purchase price.</p></div>${FINANCES.dashboard(allSummary)}<div class="quick-actions"><button class="btn secondary" data-finance-purchase>Edit purchase price</button><button class="btn secondary" data-finance-open>Edit opening YTD</button></div><div class="screen-note">Investment figures are estimates. The purchase cost is deducted only once, and unrecorded historical expenses, taxes and resale value are not included.</div>`;}
function pageTrips(){let a=state.trips.filter(t=>state.tripFilter==='all'||t.kind===state.tripFilter);a=a.slice().sort((x,y)=>(y.date||'').localeCompare(x.date||'')||(y.created_at||'').localeCompare(x.created_at||''));let km=0;for(const t of a)km+=tripDistance(t)||0;
 return `<div class="section-heading"><div><div class="eyebrow">ODOMETER LOG</div><h1>Trips</h1></div><span class="muted small">${a.length} entries</span></div><div class="quick-actions"><button class="btn" data-new-trip="work">＋ Work</button><button class="btn secondary" data-new-trip="personal">＋ Personal</button></div><div class="chip-row">${[['all','All trips'],['work','Work only'],['personal','Personal only']].map(([v,label])=>`<button class="chip ${state.tripFilter===v?'active':''}" data-trip-filter="${v}">${label}</button>`).join('')}</div><div class="card"><div class="split-line" style="margin-bottom:10px"><strong>${fmtNum(km)} km</strong><span class="muted small">Completed distance in this view</span></div>${a.length?a.map(tripLine).join(''):`<div class="empty"><div class="empty-icon">↗</div>No trips logged yet. Tap Work or Personal to begin.</div>`}</div><div class="screen-note">Enter the start odometer in the morning and save it as an open trip. Return later to add the end reading. Only completed trips are included in totals.</div>`;}
function pageExpenses(){let a=state.expenses.filter(e=>state.expenseFilter==='all'||e.category===state.expenseFilter).sort((x,y)=>(y.date||'').localeCompare(x.date||''));const spent=a.reduce((s,e)=>s+number(e.amount),0);
 return `<div class="section-heading"><div><div class="eyebrow">RUNNING COSTS</div><h1>Vehicle costs</h1></div><button class="btn smallbtn" data-new-expense>＋ Add</button></div><div class="card hero"><div class="eyebrow" style="color:#a5f4d8">TOTAL RECORDED SPENDING</div><div class="hero-value">${fmtMoney(spent)}</div><div class="hero-sub">${a.length} expense entries · All dates</div></div><div class="chip-row">${['all','Fuel','Maintenance','Repairs','Tires','Insurance','Registration','Other'].map(k=>`<button class="chip ${state.expenseFilter===k?'active':''}" data-expense-filter="${k}">${k==='all'?'All costs':k}</button>`).join('')}</div><div class="card">${a.length?a.map(expenseLine).join(''):`<div class="empty"><div class="empty-icon">▤</div>Record fuel, repairs and maintenance here. Attach a receipt for your records.</div>`}</div><div class="screen-note">Tap any expense to view or replace its receipt. Receipts are stored on this device and included in your exported backup.</div>`;}
function companyRateDescription(c){const parts=[],pct=sharePercent()/100;if(['km','both'].includes(c.mode))parts.push(`${fmtMoney(round(number(c.km_rate)*pct))}/km earned`);if(['truck_hours','both'].includes(c.mode))parts.push(`${fmtMoney(round(number(c.truck_hour_rate)*pct))}/truck hr earned`);if(c.surcharge_type&&c.surcharge_type!=='none')parts.push(`Fuel surcharge: ${c.surcharge_type==='percent'?`${fmtNum(c.surcharge_rate)}% (shared)`:c.surcharge_type==='per_km'?`${fmtMoney(round(number(c.surcharge_rate)*pct))}/km earned`:c.surcharge_type==='per_hour'?`${fmtMoney(round(number(c.surcharge_rate)*pct))}/truck hr earned`:fmtMoney(round(number(c.surcharge_rate)*pct))+' earned'}`);return parts.join(' · ')||'No charge rates set';}
function pageCompanies(){return `<div class="section-heading"><div><div class="eyebrow">COMPANY RATE CARDS</div><h1>Clients</h1></div><button class="btn smallbtn" data-new-company>＋ Add</button></div><div class="notice">Enter the client's charge-out rates; the app shows only your earnings share in summaries. Each client can have different kilometre, truck hourly and fuel surcharge pricing. Saving a trip snapshots the rates so old trip amounts stay consistent when you update prices.</div><div class="card">${state.companies.length?state.companies.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<div class="listitem"><button class="item-main" data-edit-company="${esc(c.id)}"><div class="item-title">${esc(c.name)}</div><div class="item-sub">${esc(companyRateDescription(c))}</div></button><button class="icon-button" style="background:transparent;border:0" data-edit-company="${esc(c.id)}" aria-label="Edit company">›</button></div>`).join(''):`<div class="empty"><div class="empty-icon">▦</div>Add your first client to set up custom rates and kilometre billing.</div>`}</div><div class="screen-note">You can still log work trips without selecting a client, then assign one and set its rates later.</div>`;}
function pageData(){return `<div class="section-heading"><div><div class="eyebrow">SETTINGS & YOUR RECORDS</div><h1>Data & backup</h1></div></div><div class="card"><strong>Vehicle details</strong><form id="settings-form" style="margin-top:15px"><div class="form-field"><label for="vehicle-name">Truck name (optional)</label><input id="vehicle-name" name="vehicle_name" maxlength="80" placeholder="e.g. My F-350" value="${esc(state.settings.find(s=>s.id==='vehicle_name')?.value||'')}"></div><div class="form-field"><label for="purchase-price">Truck purchase price (CAD)</label><input id="purchase-price" name="purchase_price" type="number" inputmode="decimal" min="0" step="0.01" placeholder="Optional" value="${esc(state.settings.find(s=>s.id==='vehicle_purchase_price')?.value??'')}"><p class="hint">Original truck purchase cost. Included once in lifetime return, not monthly operating costs. Avoid also counting financed principal repayments as vehicle expenses.</p></div><div class="form-field"><label for="share-percent">Your share of client charges (%)</label><input id="share-percent" name="share_percent" type="number" step="0.1" min="0" max="100" required value="${esc(sharePercent())}"><p class="hint">Default 85%. Applies to new trips. Existing trips keep their recorded earnings percentage.</p></div><div class="split-line"><span class="muted small">Currency CAD · Distance km</span><button type="submit" class="btn smallbtn">Save</button></div></form></div>
 ${FINANCES.panel()}
 ${CLOUD.panel()}
 <div class="card"><div class="split-line"><strong>Export a full backup</strong><span class="tag work">RECOMMENDED</span></div><p class="hint">Save a ZIP to your iPhone Files app or iCloud Drive. It includes all trips, clients, costs, receipt files and editable data. You can restore it after reinstalling or changing phones.</p><div class="data-buttons"><button class="btn block" data-export="backup">⇩ Export full backup (.zip)</button><button class="btn secondary block" data-export="audit">⇩ Export audit report (.pdf)</button></div><p class="hint">The audit PDF is a readable report of your complete trip log, earnings, vehicle expenses, clients and edit history, with receipt references. Keep the separate backup ZIP for restoring data and original receipt files.</p></div>
 <div class="card"><strong>Restore from a backup</strong><p class="hint">Select a ZIP created by TruckLedger. Restoring REPLACES the trips, expenses, receipts, clients and settings currently on this device. Export your current backup first.</p><div class="form-field"><label for="restore-input">Choose backup ZIP</label><input id="restore-input" type="file" accept=".zip,application/zip,application/x-zip-compressed"></div><button class="btn warn block" id="restore-btn" type="button">Restore selected backup</button></div>
 <div class="card"><strong>What is saved here?</strong><div class="datum"><span>Trip records</span><span>${state.trips.length}</span></div><div class="datum"><span>Clients</span><span>${state.companies.length}</span></div><div class="datum"><span>Vehicle expenses</span><span>${state.expenses.length}</span></div><div class="datum"><span>Receipt files</span><span>${state.receipts.length}</span></div><div class="datum"><span>Local edit-history events</span><span>${state.audit.length}</span></div><div class="notice warning">Your active records are stored locally on this device. Google Drive backup is optional and is only uploaded when you explicitly choose it. GitHub hosts the app code, not your records. iOS may remove local data if storage is cleared or the app is removed. Keep a separate backup ZIP. There is no automatic cloud synchronization.</div></div>`;}
function render(){const content=$('#content');if(!content)return;const map={dashboard:pageDashboard,trips:pageTrips,expenses:pageExpenses,companies:pageCompanies,investment:pageInvestment,data:pageData};const markup=(map[state.tab]||pageDashboard)();if(typeof MOTION!=='undefined'&&MOTION&&typeof MOTION.render==='function'){MOTION.render(content,markup,state.tab);}else{content.innerHTML='<div class="screen-stage">'+markup+'</div>';}document.querySelectorAll('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===state.tab);b.setAttribute('aria-current',b.dataset.nav===state.tab?'page':'false');});$('#offline-pill').textContent=navigator.onLine?'On-device':'Offline ready';}
function switchTab(tab){if(state.tab===tab){window.scrollTo(0,0);return;}state.tab=tab;render();window.scrollTo(0,0)}
let editorReturnScroll=0;
function useInlineEditor(){
 // On iOS installed web apps, the native <dialog> modal can interfere with touch-to-focus.
 // Use a regular page-flow form instead, keeping native dialog for Safari/desktop.
 return /iPad|iPhone|iPod/i.test(navigator.userAgent)&&
   (navigator.standalone===true||Boolean(window.matchMedia?.('(display-mode: standalone)').matches));
}
function openDialog(title,html){
 if(useInlineEditor()){
  const page=$('#editor-page');
  editorReturnScroll=window.scrollY||0;
  $('#editor-page-heading').textContent=title;
  $('#editor-page-content').innerHTML=html;
  page.hidden=false;
  document.body.classList.add('standalone-editing');
  window.scrollTo(0,0);
  return;
 }
 $('#dialog-heading').textContent=title;
 $('#dialog-content').innerHTML=html;
 const el=$('#editor');
 if(!el.open)el.showModal();
}
function closeDialog(){
 const page=$('#editor-page');
 if(page&&!page.hidden){
  // The record is persisted by its own Save action before this call.
  page.hidden=true;
  document.body.classList.remove('standalone-editing');
  $('#editor-page-content').replaceChildren();
  window.scrollTo(0,editorReturnScroll);
  return;
 }
 const el=$('#editor');if(el.open)el.close();
}
const field=(label,name,value='',opts={})=>`<div class="form-field ${opts.full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" type="${opts.type||'text'}" name="${name}" ${opts.type==='number'?'inputmode="decimal" autocomplete="off"':''} ${opts.step?`step="${opts.step}"`:''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.max!==undefined?`max="${opts.max}"`:''} ${opts.required?'required':''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} value="${esc(value??'')}"></div>`;
const selectField=(label,name,options,value='',full=false)=>`<div class="form-field ${full?'full':''}"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`;
const textArea=(label,name,value)=>`<div class="form-field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" rows="2">${esc(value||'')}</textarea></div>`;
const checked=(name,label,on)=>`<div class="checkrow"><input type="checkbox" id="f-${name}" name="${name}" ${on?'checked':''}><label for="f-${name}">${label}</label></div>`;
const nAttr='type="number" step="0.01" min="0" inputmode="decimal"';
function defaultRate(c){return {mode:c?.mode||'none',km_rate:number(c?.km_rate),truck_hour_rate:number(c?.truck_hour_rate),surcharge_type:c?.surcharge_type||'none',surcharge_rate:number(c?.surcharge_rate)};}
function openCompany(id){const c=state.companies.find(c=>c.id===id)||{id:uid(),name:'',mode:'km',km_rate:0,truck_hour_rate:0,surcharge_type:'none',surcharge_rate:0,notes:'',created_at:new Date().toISOString()};const editing=!!id;
 const html=`<form id="company-form" data-id="${esc(c.id)}"><div class="form-grid">${field('Company / client name','name',c.name,{required:true,full:true,placeholder:'e.g. Acme Construction'})}${selectField('Vehicle billing method','mode',[['km','Kilometres'],['truck_hours','Truck hours'],['both','Km + truck hours'],['none','No vehicle charges']],c.mode,true)}${field('Client charge-out rate per km (CAD)','km_rate',c.km_rate,{type:'number',step:'0.01',min:0})}${field('Client charge-out truck hourly rate (CAD)','truck_hour_rate',c.truck_hour_rate,{type:'number',step:'0.01',min:0})}${selectField('Fuel surcharge method','surcharge_type',[['none','None'],['percent','% of vehicle charges'],['per_km','CAD per actual km'],['per_hour','CAD per truck hour'],['flat','CAD flat per trip']],c.surcharge_type)}${field('Fuel surcharge amount','surcharge_rate',c.surcharge_rate,{type:'number',step:'0.01',min:0})}${textArea('Notes / contract details','notes',c.notes)}</div><div class="notice">These rates are the amounts charged to the client before your share. Truck hours are optional unless you use hourly billing or an hourly fuel surcharge. A surcharge can apply even when kilometres or truck hours aren't separately billed.</div><div class="foot-actions"><button class="btn" type="submit">${editing?'Save changes':'Save client'}</button>${editing?`<button class="btn warn" type="button" data-delete-company="${esc(c.id)}">Delete</button>`:''}</div></form>`;
 openDialog(editing?'Edit client':'Add client',html);
}
function parsePositive(v,label,allowEmpty=false){if(v===''&&allowEmpty)return null;const x=Number(v);if(v===''||!Number.isFinite(x)||x<0)throw new Error(`${label} must be a valid non-negative number`);return x;}
async function saveCompany(f){const prior=state.companies.find(c=>c.id===f.dataset.id);const record={id:f.dataset.id,name:f.elements.name.value.trim(),mode:f.elements.mode.value,km_rate:parsePositive(f.elements.km_rate.value,'Km rate'),truck_hour_rate:parsePositive(f.elements.truck_hour_rate.value,'Truck hourly rate'),surcharge_type:f.elements.surcharge_type.value,surcharge_rate:parsePositive(f.elements.surcharge_rate.value,'Fuel surcharge'),notes:f.elements.notes.value.trim(),created_at:prior?.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};if(prior&&'labour_hour_rate' in prior)record.labour_hour_rate=prior.labour_hour_rate;if(!record.name)throw new Error('Please enter a company name');await writeWithAudit('companies',record,prior);closeDialog();await refresh();toast('Client saved');}
function companyOpts(selected){return [['','Unassigned — set later'],...state.companies.map(c=>[c.id,c.name])];}
function openTrip(kind,id){const previous=state.trips.find(t=>t.id===id);const t=previous?structuredClone(previous):{id:uid(),kind:kind||'work',date:today(),start_km:'',end_km:null,billed_km:null,client_id:'',client_name:'',destination:'',purpose:'',truck_hours:'',notes:'',rate:defaultRate(null),bill_km:false,bill_truck_hours:false,bill_surcharge:false,share_percent:sharePercent(),created_at:new Date().toISOString()};const work=t.kind==='work',rate=t.rate||defaultRate(getCompany(t.client_id));const edit=!!previous;
 const html=`<form id="trip-form" data-id="${esc(t.id)}" data-kind="${t.kind}"><div class="form-grid">${field('Date','date',t.date,{type:'date',required:true,full:true})}${field('Start odometer (km)','start_km',t.start_km,{type:'number',step:'0.1',min:0,required:true})}${field('End odometer (km)','end_km',t.end_km,{type:'number',step:'0.1',min:0,placeholder:'Enter later'})}<div class="odometer-live full" id="odometer-live" aria-live="off"><span class="odometer-live-icon" aria-hidden="true">↗</span><div class="odometer-live-copy"><span class="odometer-live-label">DISTANCE DRIVEN</span><span class="odometer-live-detail" id="odometer-live-detail">Add an ending odometer reading to calculate the trip.</span></div><strong class="odometer-live-value" id="odometer-live-value">— km</strong></div>${work?`${field('Billed kilometres','billed_km',t.billed_km,{type:'number',step:'0.1',min:0,full:true,placeholder:'Blank = actual kilometres'})}<p class="hint" style="grid-column:1/-1;margin-top:-8px">Optional. Leave blank to bill the actual odometer distance. Enter a different number to track extra billed km.</p>${selectField('Client / company','client_id',companyOpts(),t.client_id,true)}${field('Location / destination','destination',t.destination,{full:true,placeholder:'Job site, town, route'})}${textArea('What were you doing?','purpose',t.purpose)}${field('Truck hours (hourly billing or surcharge)','truck_hours',t.truck_hours===''||t.truck_hours==null?((t.bill_truck_hours||t.rate?.surcharge_type==='per_hour')?t.hours||'':''):t.truck_hours,{type:'number',step:'0.25',min:0,placeholder:'Hours for hourly rates'})}`:`${field('Where did you go?','destination',t.destination,{full:true,placeholder:'e.g. Shopping in Dawson Creek'})}${textArea('Reason / notes','purpose',t.purpose)}`}${textArea('Other notes','notes',t.notes)}</div>
 ${work?`<div class="form-divider">Client billing for this trip</div><div class="hint">An hourly fuel surcharge uses the truck hours entered above, even if truck-hour billing is off.</div><div id="trip-charges">${checked('bill_km','Charge the client for kilometres',t.bill_km)}${checked('bill_truck_hours','Charge for truck hours',t.bill_truck_hours)}${checked('bill_surcharge','Apply fuel surcharge',t.bill_surcharge)}</div>
 <details id="rates-details"><summary class="inline-link">Adjust rates for this trip</summary><p class="hint">These numbers are captured with this entry. Updating the client later will not change them.</p><div class="form-grid">${field('Price per km','km_rate',rate.km_rate,{type:'number',step:'0.01',min:0})}${field('Truck hourly price','truck_hour_rate',rate.truck_hour_rate,{type:'number',step:'0.01',min:0})}${selectField('Fuel surcharge type','surcharge_type',[['none','None'],['percent','% of vehicle charges'],['per_km','CAD per actual km'],['per_hour','CAD per truck hour'],['flat','CAD flat per trip']],rate.surcharge_type)}${field('Fuel surcharge rate','surcharge_rate',rate.surcharge_rate,{type:'number',step:'0.01',min:0})}</div></details>`:''}
 <div class="previewbox" id="trip-preview"></div><div class="foot-actions"><button class="btn" type="submit">${edit?'Save trip':'Add trip'}</button>${edit?`<button class="btn warn" type="button" data-delete-trip="${esc(t.id)}">Delete</button>`:''}</div></form>`;
 openDialog(edit?`Edit ${work?'work':'personal'} trip`:`New ${work?'work':'personal'} trip`,html);const f=$('#trip-form');f.dataset.editing=edit?'1':'0';f.dataset.initialClient=t.client_id||'';f.dataset.sharePercent=String(tripSharePercent(t));updateTripPreview();}
function applyCompanyToTrip(form){const c=getCompany(form.elements.client_id?.value);const r=defaultRate(c);for(const key of ['km_rate','truck_hour_rate','surcharge_type','surcharge_rate']){if(form.elements[key])form.elements[key].value=r[key];}form.elements.bill_km.checked=['km','both'].includes(r.mode);form.elements.bill_truck_hours.checked=['truck_hours','both'].includes(r.mode);form.elements.bill_surcharge.checked=r.surcharge_type!=='none'&&r.surcharge_rate>0;updateTripPreview();}
function readTripForm(f){const work=f.dataset.kind==='work';const el=f.elements;const start=el.start_km.value;const end=el.end_km.value;const startNum=start===''?null:Number(start),endNum=end===''?null:Number(end);const r=work?{mode:'custom',km_rate:number(el.km_rate.value),truck_hour_rate:number(el.truck_hour_rate.value),surcharge_type:el.surcharge_type.value,surcharge_rate:number(el.surcharge_rate.value)}:null;return {id:f.dataset.id,kind:f.dataset.kind,date:el.date.value,start_km:startNum,end_km:endNum,billed_km:work?(el.billed_km.value===''?null:Number(el.billed_km.value)):null,client_id:work?el.client_id.value:'',client_name:work?getCompany(el.client_id.value)?.name||'':'',destination:el.destination.value.trim(),purpose:el.purpose.value.trim(),notes:el.notes.value.trim(),truck_hours:work?el.truck_hours.value:'',share_percent:work?Number(f.dataset.sharePercent??DEFAULT_EARNINGS_SHARE):DEFAULT_EARNINGS_SHARE,rate:r,bill_km:work?el.bill_km.checked:false,bill_truck_hours:work?el.bill_truck_hours.checked:false,bill_surcharge:work?el.bill_surcharge.checked:false};}
function updateTripPreview(){const f=$('#trip-form'),out=$('#trip-preview');if(!f||!out)return;const t=readTripForm(f);
 const summary=$('#odometer-live');
 if(summary){
  const complete=t.start_km!==null&&t.end_km!==null&&Number.isFinite(t.start_km)&&Number.isFinite(t.end_km)&&t.end_km>=t.start_km;
  const invalid=t.start_km!==null&&t.end_km!==null&&Number.isFinite(t.start_km)&&Number.isFinite(t.end_km)&&t.end_km<t.start_km;
  const wasReady=summary.classList.contains('is-ready');
  summary.classList.toggle('is-ready',complete);
  summary.classList.toggle('is-invalid',invalid);
  summary.classList.toggle('just-ready',complete&&!wasReady);
  const value=$('#odometer-live-value'),detail=$('#odometer-live-detail');
  if(value)value.textContent=complete?fmtNum(round(t.end_km-t.start_km))+' km':invalid?'Check km':'— km';
  if(detail)detail.textContent=complete?'Calculated from your odometer readings':invalid?'Ending km must be at least the starting km':'You can finish this trip later';
 }
 if(t.start_km===null){out.innerHTML='<div class="hint">Enter the morning odometer reading to start a trip.</div>';return;}if(t.end_km===null){out.innerHTML='<div class="eyebrow">OPEN TRIP</div><div class="total">Finish later</div><div class="hint">Save now and enter the evening odometer when you get home.</div>';return;}if(t.end_km<t.start_km){out.innerHTML='<span class="danger">End odometer must be at least the start odometer.</span>';return;}const c=calculate(t);out.innerHTML=`<div class="eyebrow">TRIP SUMMARY</div>${t.kind==='work'&&FINANCES.covered(t)?'<div class="notice">This trip falls inside your opening YTD period; its earnings will not be added twice to your totals.</div>':''}<div class="total">${fmtNum(c.km)} km</div>${t.kind==='work'?`<div class="datum"><span>Actual distance</span><span>${fmtNum(c.km)} km</span></div><div class="datum"><span>Billed kilometres</span><span>${t.bill_km?`${fmtNum(c.billedKm)} km`:'Not billed'}</span></div>${t.bill_km?`<div class="datum"><span>Difference (billed − driven)</span><span>${c.billedKm-c.km>0?'+':''}${fmtNum(round(c.billedKm-c.km))} km</span></div>`:''}<div class="hint">Your earnings share: ${fmtNum(c.sharePercent)}% of charges</div><div class="datum"><span>Your km earnings</span><span>${fmtMoney(c.kmCharge)}</span></div><div class="datum"><span>Your truck-hour earnings</span><span>${fmtMoney(c.truckCharge)}</span></div><div class="datum"><span>Your fuel surcharge earnings</span><span>${fmtMoney(c.surcharge)}</span></div><div class="datum"><strong>Your trip earnings</strong><strong>${fmtMoney(c.truckRevenue)}</strong></div>`:'<div class="hint">Personal kilometres are tracked but never billed.</div>'}`;}
async function saveTrip(f){const t=readTripForm(f);if(!t.date)throw new Error('Please choose a date');if(t.start_km===null||!Number.isFinite(t.start_km)||t.start_km<0)throw new Error('Enter a valid starting odometer reading');if(t.end_km!==null&&(!Number.isFinite(t.end_km)||t.end_km<t.start_km))throw new Error('The end odometer cannot be less than the start');if(t.kind==='work'){if(t.billed_km!==null&&(!Number.isFinite(t.billed_km)||t.billed_km<0))throw new Error('Billed kilometres must be a non-negative number');for(const k of ['truck_hours'])if(t[k]!==''&&(!Number.isFinite(Number(t[k]))||Number(t[k])<0))throw new Error('Truck hours cannot be negative');for(const k of ['km_rate','truck_hour_rate','surcharge_rate'])if(!Number.isFinite(t.rate[k])||t.rate[k]<0)throw new Error('Rates must be non-negative');}
 // An edit can legitimately overlap a work day on which the vehicle was used personally.
 const prior=state.trips.find(x=>x.id===t.id);/* Preserve any legacy labour fields in stored history, without collecting or billing them. */if(prior){if('hours' in prior)t.hours=prior.hours;if('bill_labour' in prior)t.bill_labour=prior.bill_labour;if(t.rate&&prior.rate&&'labour_hour_rate' in prior.rate)t.rate.labour_hour_rate=prior.rate.labour_hour_rate;}t.created_at=prior?.created_at||new Date().toISOString();t.updated_at=new Date().toISOString();
 await writeWithAudit('trips',t,prior);closeDialog();await refresh();toast(t.end_km===null?'Open trip saved — finish it later':'Trip saved');}
function openExpense(id){const old=state.expenses.find(e=>e.id===id);const e=old?structuredClone(old):{id:uid(),date:today(),category:'Fuel',amount:'',vendor:'',odometer:'',litres:'',notes:'',receipt_id:'',created_at:new Date().toISOString()};const edit=!!old;
 const html=`<form id="expense-form" data-id="${esc(e.id)}"><div class="form-grid">${field('Date','date',e.date,{type:'date',required:true})}${selectField('Category','category',['Fuel','Maintenance','Repairs','Tires','Insurance','Registration','Other'].map(x=>[x,x]),e.category)}${field('Cost (CAD)','amount',e.amount,{type:'number',step:'0.01',min:0,required:true})}${field('Merchant / workshop','vendor',e.vendor,{placeholder:'e.g. Shell, Canadian Tire'})}${field('Odometer (optional)','odometer',e.odometer,{type:'number',step:'0.1',min:0})}${field('Litres (for fuel)','litres',e.litres,{type:'number',step:'0.001',min:0})}${textArea('Notes / work performed','notes',e.notes)}</div><div class="form-divider">Receipt</div><div class="form-field"><label for="receipt-file">Take a photo or attach a PDF/image</label><input type="file" id="receipt-file" name="receipt_file" accept="image/*,application/pdf"></div><div id="receipt-status" class="hint">${e.receipt_id?'Receipt attached to this expense. Choose a new file to replace it.':'Optional; no receipt attached.'}</div>${e.receipt_id?`<div class="actions" style="margin-top:10px"><button class="btn ghost smallbtn" type="button" data-view-receipt="${esc(e.receipt_id)}">View receipt</button><button class="btn warn smallbtn" type="button" data-remove-receipt="${esc(e.receipt_id)}">Remove receipt</button></div>`:''}<div class="foot-actions"><button class="btn" type="submit">${edit?'Save expense':'Add expense'}</button>${edit?`<button class="btn warn" data-delete-expense="${esc(e.id)}" type="button">Delete</button>`:''}</div></form>`;
 openDialog(edit?'Edit vehicle cost':'Add vehicle cost',html);}
async function saveExpense(f){const old=state.expenses.find(e=>e.id===f.dataset.id);const el=f.elements;const amt=parsePositive(el.amount.value,'Cost');if(!el.date.value)throw new Error('Choose a date');if(el.odometer.value!=='')parsePositive(el.odometer.value,'Odometer');if(el.litres.value!=='')parsePositive(el.litres.value,'Litres');const input=el.receipt_file.files[0];if(input&&input.size>20*1024*1024)throw new Error('Receipt must be smaller than 20 MB');if(input&&!(/^(image\/(jpeg|png|webp|gif|heic|heif)|application\/pdf)$/i.test(input.type)||/\.(jpe?g|png|webp|gif|heic|heif|pdf)$/i.test(input.name)))throw new Error('Please use an image or PDF receipt');
 let receiptId=f.dataset.removeReceipt==='1'?'':old?.receipt_id||'';let newReceipt=null;
 if(input){receiptId=uid();const safeName=input.name.replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,120)||'receipt';newReceipt={id:receiptId,name:safeName,mime:input.type||'application/octet-stream',size:input.size,blob:input,created_at:new Date().toISOString()};}
 const e={id:f.dataset.id,date:el.date.value,category:el.category.value,amount:amt,vendor:el.vendor.value.trim(),odometer:el.odometer.value===''?'':Number(el.odometer.value),litres:el.litres.value===''?'':Number(el.litres.value),notes:el.notes.value.trim(),receipt_id:receiptId,created_at:old?.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};
 // Commit expense and any receipt changes atomically.
 await new Promise((resolve,reject)=>{const tx=state.db.transaction(['expenses','receipts','audit'],'readwrite');tx.objectStore('expenses').put(e);tx.objectStore('audit').put(auditEvent('expenses',old?'update':'create',old,e));if(newReceipt)tx.objectStore('receipts').put(newReceipt);if(old?.receipt_id&&old.receipt_id!==receiptId)tx.objectStore('receipts').delete(old.receipt_id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Save interrupted'));});closeDialog();await refresh();toast('Vehicle cost saved');}
async function showReceipt(id){const record=await get('receipts',id);if(!record){toast('Receipt not found');return;}const blob=record.blob;const url=URL.createObjectURL(blob);const pdf=record.mime==='application/pdf'||record.name.toLowerCase().endsWith('.pdf');openDialog('Attached receipt',`<div class="file-row">${esc(record.name)} · ${(number(record.size)/1024/1024).toFixed(2)} MB</div>${pdf?'<p class="hint">PDF receipts can be opened in Safari or downloaded using the button below.</p>':`<img class="receipt-preview" src="${url}" alt="Receipt image">`}<div class="actions"><a class="btn" target="_blank" rel="noopener" href="${url}">Open receipt</a><a class="btn secondary" download="${esc(record.name)}" href="${url}">Save file</a></div>`);$('#editor').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
async function deleteRecord(store,id){const names={companies:'client',trips:'trip',expenses:'expense'};if(!confirm(`Delete this ${names[store]}? This cannot be undone.`))return;const old=store==='expenses'?state.expenses.find(x=>x.id===id):null;
 if(store==='expenses'&&old?.receipt_id)await new Promise((resolve,reject)=>{const tx=state.db.transaction(['expenses','receipts','audit'],'readwrite');tx.objectStore('expenses').delete(id);tx.objectStore('receipts').delete(old.receipt_id);tx.objectStore('audit').put(auditEvent(store,'delete',old,null));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});else await new Promise((resolve,reject)=>{const tx=state.db.transaction([store,'audit'],'readwrite');const prior=store==='trips'?state.trips.find(t=>t.id===id):store==='companies'?state.companies.find(c=>c.id===id):old;tx.objectStore(store).delete(id);tx.objectStore('audit').put(auditEvent(store,'delete',prior,null));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});
 closeDialog();await refresh();toast('Entry deleted');}
function csvCell(x){let s=String(x??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function csv(columns,rows){return '\uFEFF'+[columns.map(csvCell).join(','),...rows.map(r=>r.map(csvCell).join(','))].join('\r\n')+'\r\n';}
const u8=s=>new TextEncoder().encode(s);
function makeCRC(data){let c=-1;for(let i=0;i<data.length;i++){c^=data[i];for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^(-1))>>>0;}
const w16=(v,o,n)=>v.setUint16(o,n,true),w32=(v,o,n)=>v.setUint32(o,n>>>0,true);
function buildZip(entries){const local=[],central=[];let pos=0;for(const e of entries){const name=u8(e.name),data=e.data,crc=makeCRC(data),l=new Uint8Array(30+name.length),lv=new DataView(l.buffer);w32(lv,0,0x04034b50);w16(lv,4,20);w16(lv,6,0x0800);w16(lv,8,0);w16(lv,10,0);w16(lv,12,0);w32(lv,14,crc);w32(lv,18,data.length);w32(lv,22,data.length);w16(lv,26,name.length);w16(lv,28,0);l.set(name,30);local.push(l,data);
 const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);w32(cv,0,0x02014b50);w16(cv,4,20);w16(cv,6,20);w16(cv,8,0x0800);w16(cv,10,0);w16(cv,12,0);w16(cv,14,0);w32(cv,16,crc);w32(cv,20,data.length);w32(cv,24,data.length);w16(cv,28,name.length);w16(cv,30,0);w16(cv,32,0);w16(cv,34,0);w16(cv,36,0);w32(cv,38,0);w32(cv,42,pos);c.set(name,46);central.push(c);pos+=l.length+data.length;}
 const cdLength=central.reduce((sum,c)=>sum+c.length,0),end=new Uint8Array(22),dv=new DataView(end.buffer);w32(dv,0,0x06054b50);w16(dv,8,entries.length);w16(dv,10,entries.length);w32(dv,12,cdLength);w32(dv,16,pos);return new Blob([...local,...central,end],{type:'application/zip'});}
function readZip(bytes){const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);const out=new Map();let p=0;while(p+30<=bytes.length){const sig=view.getUint32(p,true);if(sig===0x02014b50||sig===0x06054b50)break;if(sig!==0x04034b50)throw new Error('Backup ZIP is not recognized');const flags=view.getUint16(p+6,true),method=view.getUint16(p+8,true),compressed=view.getUint32(p+18,true),size=view.getUint32(p+22,true),nameLength=view.getUint16(p+26,true),extraLength=view.getUint16(p+28,true);if(flags&8||method!==0||compressed!==size)throw new Error('This ZIP is not a TruckLedger backup (unsupported compression)');const nameStart=p+30,dataStart=nameStart+nameLength+extraLength;if(dataStart+size>bytes.length)throw new Error('Incomplete ZIP file');const name=new TextDecoder().decode(bytes.slice(nameStart,nameStart+nameLength));const data=bytes.slice(dataStart,dataStart+size);if(makeCRC(data)!==view.getUint32(p+14,true))throw new Error('Backup ZIP has a damaged file');out.set(name,data);p=dataStart+size;}return out;}
const safeReceiptPath=r=>`receipts/${r.id}/${r.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;
async function makeExport(mode){const receiptManifest=state.receipts.map(r=>({id:r.id,name:r.name,mime:r.mime,size:r.size,created_at:r.created_at,path:safeReceiptPath(r)}));const dataset={format:'truckledger-v1',schema_version:2,exported_at:new Date().toISOString(),companies:state.companies,trips:state.trips,expenses:state.expenses,settings:state.settings,audit:state.audit,receipts:receiptManifest};
 const files=[{name:'data.json',data:u8(JSON.stringify(dataset,null,2))},{name:'README.txt',data:u8('TruckLedger export — '+dataset.exported_at+'\r\nAll amounts in Canadian dollars, distances in kilometres.\r\nAll files are stored on-device until you export.\r\nTo restore, use Data & backup > Restore selected backup.\r\nTrip client rates and charges are snapshots; historical totals stay unchanged when company rates are edited.\r\nReceipts are held in receipts/ and are referenced by expenses.csv and data.json.\r\nchange_history.csv is a locally maintained edit history; it is not tamper-proof.\r\nZIP is intentionally uncompressed for compatibility with the in-app restore tool.\r\n')}];
 if(mode==='audit'){
 const workCols=['ID','Date','Client','Destination','Work description','Start km','End km','Distance km','Truck billable hours','Km billed','Truck hours billed','Fuel surcharge billed','Rate per km','Truck hourly rate','Surcharge type','Surcharge rate','Your share percent','Your km earnings CAD','Your truck-hour earnings CAD','Your fuel surcharge earnings CAD','Your total earnings CAD','Notes','Created at','Updated at'];
 const workRows=state.trips.filter(t=>t.kind==='work').sort((a,b)=>a.date.localeCompare(b.date)).map(t=>{const c=calculate(t);return[t.id,t.date,companyName(t),t.destination,t.purpose,t.start_km,t.end_km??'',c.km??'',t.truck_hours||((t.bill_truck_hours&&t.hours)||''),t.bill_km,t.bill_truck_hours,t.bill_surcharge,t.rate?.km_rate,t.rate?.truck_hour_rate,t.rate?.surcharge_type,t.rate?.surcharge_rate,tripSharePercent(t),c.kmCharge,c.truckCharge,c.surcharge,c.truckRevenue,t.notes,t.created_at,t.updated_at];});
 files.push({name:'work_trips.csv',data:u8(csv(workCols,workRows))});
 files.push({name:'personal_trips.csv',data:u8(csv(['ID','Date','Destination','Reason','Start km','End km','Distance km','Notes','Created at','Updated at'],state.trips.filter(t=>t.kind==='personal').sort((a,b)=>a.date.localeCompare(b.date)).map(t=>[t.id,t.date,t.destination,t.purpose,t.start_km,t.end_km??'',tripDistance(t)??'',t.notes,t.created_at,t.updated_at])))});
 files.push({name:'clients.csv',data:u8(csv(['ID','Name','Vehicle billing mode','Rate per km CAD','Truck hourly rate CAD','Surcharge type','Surcharge rate','Notes','Created at','Updated at'],state.companies.map(c=>[c.id,c.name,c.mode,c.km_rate,c.truck_hour_rate,c.surcharge_type,c.surcharge_rate,c.notes,c.created_at,c.updated_at])))});
 files.push({name:'vehicle_expenses.csv',data:u8(csv(['ID','Date','Category','Amount CAD','Merchant','Odometer km','Litres','Notes','Receipt file','Created at','Updated at'],state.expenses.map(e=>[e.id,e.date,e.category,e.amount,e.vendor,e.odometer,e.litres,e.notes,receiptManifest.find(r=>r.id===e.receipt_id)?.path||'',e.created_at,e.updated_at])))});
 files.push({name:'change_history.csv',data:u8(csv(['Event ID','Timestamp','Entity','Action','Record ID','Before JSON','After JSON'],state.audit.slice().sort((a,b)=>(a.at||'').localeCompare(b.at||'')).map(e=>[e.id,e.at,e.entity,e.action,e.record_id,JSON.stringify(e.before),JSON.stringify(e.after)])))});
 }
 for(const r of state.receipts){const blob=r.blob instanceof Blob?r.blob:new Blob([r.blob],{type:r.mime});files.push({name:safeReceiptPath(r),data:new Uint8Array(await blob.arrayBuffer())});}
 return buildZip(files);}
function saveDownload(blob,filename){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
let exporting=false;
async function exportData(mode){if(exporting)return;exporting=true;const btn=document.querySelector(`[data-export="${mode}"]`);if(btn){btn.disabled=true;btn.textContent='Preparing ZIP…';}try{if(mode==='audit'){const blob=await makeAuditPDF();const filename=`TruckLedger_Audit_${today()}.pdf`;const file=new File([blob],filename,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'TruckLedger audit report'});}catch(e){if(e.name!=='AbortError')saveDownload(blob,filename);}}else saveDownload(blob,filename);toast('Audit PDF ready — save it in Files');}else{const blob=await makeExport('backup');saveDownload(blob,`TruckLedger_backup_${today()}.zip`);toast('Backup ZIP ready — save it in Files or iCloud Drive');}}catch(e){alert('Export failed: '+e.message)}finally{exporting=false;if(btn){btn.disabled=false;btn.textContent=mode==='audit'?'⇩ Export audit report (.pdf)':'⇩ Export full backup (.zip)';}}}
async function restoreBackup(file){if(!file)throw new Error('Choose a ZIP backup first');if(file.size>300*1024*1024)throw new Error('Backup is larger than 300 MB; this version cannot restore it on-device');const entries=readZip(new Uint8Array(await file.arrayBuffer()));const dataFile=entries.get('data.json');if(!dataFile)throw new Error('No data.json found in this archive');let data;try{data=JSON.parse(new TextDecoder().decode(dataFile));}catch{throw new Error('The data file is not valid JSON');}
 if(data?.format!=='truckledger-v1'||![1,2].includes(data.schema_version)||!['companies','trips','expenses','settings','receipts'].every(k=>Array.isArray(data[k]))||(data.audit!==undefined&&!Array.isArray(data.audit)))throw new Error('Not a supported TruckLedger v1 backup');
 for(const group of ['companies','trips','expenses','settings','audit'])for(const r of (data[group]||[]))if(!r||typeof r.id!=='string')throw new Error(`Invalid ${group} record in backup`);
 const receiptRecords=[];for(const r of data.receipts){if(!r||typeof r.id!=='string'||typeof r.path!=='string'||!r.path.startsWith('receipts/'))throw new Error('Invalid receipt in backup');const b=entries.get(r.path);if(!b)throw new Error('A receipt file is missing: '+r.name);receiptRecords.push({id:r.id,name:r.name,mime:r.mime,size:b.length,blob:new Blob([b],{type:r.mime||'application/octet-stream'}),created_at:r.created_at});}
 const prompt=`Restore ${data.trips.length} trips, ${data.companies.length} clients, ${data.expenses.length} expenses and ${receiptRecords.length} receipt files?\n\nThis will REPLACE your current data on this device. Cancel if you have not exported a backup of your current entries.`;if(!confirm(prompt))return false;
 await new Promise((resolve,reject)=>{const tx=state.db.transaction(STORES,'readwrite');for(const n of STORES)tx.objectStore(n).clear();for(const group of ['companies','trips','expenses','settings','audit'])for(const r of (data[group]||[]))tx.objectStore(group).put(r);for(const r of receiptRecords)tx.objectStore('receipts').put(r);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Restore interrupted'));});await refresh();toast('Backup restored successfully');return true;}
async function routeClick(e){const btn=e.target.closest('button');if(!btn)return;try{
 if(btn.dataset.nav){switchTab(btn.dataset.nav);return;}if(btn.dataset.period){if(state.period!==btn.dataset.period){state.period=btn.dataset.period;state.trendFocus=-1;render();}return;}if(btn.dataset.tripFilter){state.tripFilter=btn.dataset.tripFilter;render();return;}if(btn.dataset.expenseFilter){state.expenseFilter=btn.dataset.expenseFilter;render();return;}if(btn.dataset.newTrip){openTrip(btn.dataset.newTrip);return;}if(btn.hasAttribute('data-new-expense')){openExpense();return;}if(btn.hasAttribute('data-new-company')){openCompany();return;}
 if(btn.dataset.editTrip){openTrip(null,btn.dataset.editTrip);return;}if(btn.dataset.editExpense){openExpense(btn.dataset.editExpense);return;}if(btn.dataset.editCompany){openCompany(btn.dataset.editCompany);return;}
 if(btn.dataset.deleteTrip){await deleteRecord('trips',btn.dataset.deleteTrip);return;}if(btn.dataset.deleteExpense){await deleteRecord('expenses',btn.dataset.deleteExpense);return;}if(btn.dataset.deleteCompany){await deleteRecord('companies',btn.dataset.deleteCompany);return;}
 if(btn.dataset.viewReceipt){await showReceipt(btn.dataset.viewReceipt);return;}if(btn.dataset.removeReceipt){if(confirm('Remove this receipt from the expense? The change is saved when you save the expense.')){$('#expense-form').dataset.removeReceipt='1';$('#receipt-status').textContent='Receipt will be removed when you save this expense.';btn.closest('.actions').remove();}return;}
 if(btn.dataset.export){await exportData(btn.dataset.export);return;}if(btn.id==='restore-btn'){const input=$('#restore-input');try{await restoreBackup(input?.files?.[0]);}catch(err){alert('Restore failed: '+err.message)}return;}if(btn.id==='close-dialog'||btn.id==='close-editor-page'){closeDialog();return;}
 }catch(err){alert(err.message||'Something went wrong');console.error(err);}}
async function routeSubmit(event){const f=event.target;if(!['company-form','trip-form','expense-form','settings-form'].includes(f.id))return;event.preventDefault();const submit=f.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{if(f.id==='company-form')await saveCompany(f);else if(f.id==='trip-form')await saveTrip(f);else if(f.id==='expense-form')await saveExpense(f);else if(f.id==='settings-form'){const value=parsePositive(f.elements.share_percent.value,'Earnings share');if(value>100)throw new Error('Earnings share cannot be above 100%');const purchase=f.elements.purchase_price.value===''?'':parsePositive(f.elements.purchase_price.value,'Truck purchase price');const old=state.settings.find(x=>x.id==='vehicle_name');await writeWithAudit('settings',{id:'vehicle_name',value:f.elements.vehicle_name.value.trim()},old);const priorPurchase=state.settings.find(x=>x.id==='vehicle_purchase_price');await writeWithAudit('settings',{id:'vehicle_purchase_price',value:purchase},priorPurchase);const oldShare=state.settings.find(x=>x.id==='share_percent');await writeWithAudit('settings',{id:'share_percent',value},oldShare);await refresh();toast('Vehicle settings saved — new trips use your share');}}catch(e){alert(e.message||'Save failed');console.error(e)}finally{if(submit?.isConnected)submit.disabled=false;}}
function routeInput(e){if(e.target.closest('#trip-form')){const f=$('#trip-form');if(e.target.name==='client_id'){applyCompanyToTrip(f);}else updateTripPreview();}if(e.target.id==='receipt-file'){const file=e.target.files?.[0];$('#receipt-status').textContent=file?`${file.name} (${(file.size/1024/1024).toFixed(2)} MB) ready to save`:'No new receipt selected';}}
async function init(){document.addEventListener('click',routeClick);document.addEventListener('submit',routeSubmit);document.addEventListener('input',routeInput);document.addEventListener('change',routeInput);$('#editor').addEventListener('click',e=>{if(e.target===$('#editor'))closeDialog();});window.addEventListener('online',render);window.addEventListener('offline',render);
 try{state.db=await openDB();await refresh();if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline install unavailable',err));}
 catch(e){const storageIssue=/indexeddb|storage|database/i.test(String(e?.message||''));$('#content').innerHTML=storageIssue?
 `<div class="card"><h1>Device storage unavailable</h1><p>TruckLedger cannot access local storage. Don't remove the app or clear its website data until your records are backed up.</p><p class="danger">${esc(e.message)}</p></div>`:
 `<div class="card"><h1>App loading issue</h1><p>One of the app components didn't load correctly. Your saved mileage records have not been deleted.</p><p class="danger">${esc(e.message)}</p><p>Reconnect to the internet, then close and reopen the app. Do not clear website data.</p></div>`;console.error(e);}}
init();
